// Meta answers refused messages with a normal response, so turn them into a real error (it reaches Fenjan 2 and Telegram).
const r = $input.first().json;
const code = Number(r.statusCode || 0);
if (code >= 400 || r.error) {
  const why = String(r.error?.message || r.headers?.['www-authenticate'] || r.body || 'Unknown reason').slice(0, 300);
  throw new Error('Meta did not deliver the reply to ' + $('Decide Reply').first().json.platform + ' customer ' + $('Decide Reply').first().json.sender_id + ': ' + why);
}
return [{ json: { delivered: true, message_id: r.message_id || '' } }];

const items = $input.all().map(i => i.json).filter(r => String(r.available || '').toLowerCase() === 'yes');
if (!items.length) return [];
const dayIndex = Math.floor(Date.now() / 86400000);
const pick = items[dayIndex % items.length];
const post = `صباح الخير من فنجان ☕\nعرض النهاردة: ${pick.name_ar} (${pick.name_en}) بـ ${pick.price_egp} ج.م بس!\n\nابعتلنا رسالة هنا على الصفحة أو إنستجرام واطلبه دلوقتي (استلام أو دليفري) 🚀`;
return [{ json: { message: post } }];

const f = $('Kitchen Update').first().json;
const id = String(f.order_id || '').trim().toUpperCase(), status = f.status, note = String(f.note || '').trim().slice(0, 300);
const o = $input.all().map(i => i.json).find(r => String(r.order_id || '').toUpperCase() === id);
const problems = [];
if (!/^F-\d{6}-[A-Z0-9]{4}$/.test(id)) problems.push('Order ID should look like F-261126-AB12');
else if (!o) problems.push(`Order ${id} was not found in the Orders sheet`);
else if (['cancelled'].includes(o.status) && status !== 'cancelled') problems.push(`Order ${id} is already cancelled`);
if (o && status === 'out_for_delivery' && o.fulfilment !== 'delivery') problems.push(`Order ${id} is a pickup order`);

const ar = o?.language === 'ar';
const t = (en, a) => ar ? a : en;
const msgs = {
  preparing: t(`We are preparing your order ${id} now.`, `بنحضر طلبك ${id} دلوقتي.`),
  ready: t(`Your order ${id} is ready for pickup! See you at Fenjan.`, `طلبك ${id} جاهز للاستلام! مستنيينك في فنجان.`),
  out_for_delivery: t(`Your order ${id} is on the way to ${o?.address || 'you'}.`, `طلبك ${id} في الطريق ليك على ${o?.address || 'عنوانك'}.`),
  cancelled: t(`Sorry, we had to cancel order ${id}. Reply here and we will sort it out.`, `للأسف اضطرينا نلغي الطلب ${id}. رد علينا هنا وهنحلها.`),
};

return [{
  json: {
    ok: problems.length === 0,
    problems,
    order_id: id,
    status,
    customer_id: o?.customer_id || '',
    platform: o?.platform || '',
    message: (msgs[status] || '') + (note ? '\n' + note : ''),
    now: $now.setZone('Africa/Cairo').toFormat('yyyy-MM-dd HH:mm')
  }
}];
